      res.writeHead(200, { 'content-type': 'text/plain' });
      res.end('cfo.ai is connected. You can close this tab.\n');
      resolveCode(received);
    } else {
      res.writeHead(400, { 'content-type': 'text/plain' });
      res.end('Missing OAuth code.\n');
