const envPath = path.join(os.homedir(), '.tally', '.env');
const envText = fs.readFileSync(envPath, 'utf8');
const match = envText.match(/^(?:export\s+)?NEATLOGS_API_KEY\s*=\s*(.*)$/m);
if (!match) throw new Error('NEATLOGS_API_KEY missing');
const key = match[1].trim().replace(/^(.*)$/, '$1').replace(/^['\"]|['\"]$/g, '');
const scratch = fs.mkdtempSync(path.join(os.tmpdir(), 'neatlogs-claude-check-'));
const result = spawnSync('claude', ['-p', 'Reply with exactly: neatlogs hook check', '--output-format', 'text'], {
  cwd: scratch,
  env: { ...process.env, NEATLOGS_API_KEY: key },
  encoding: 'utf8',
  maxBuffer: 1024 * 1024,
});
process.stdout.write(result.stdout);
process.stderr.write(result.stderr);
process.exit(result.status ?? 1);
